from pathlib import Path
from datetime import datetime,timezone
import json,hashlib,sys
sys.path.insert(0,str(Path(__file__).resolve().parents[4]))
from math_collab.campaigns import validate_campaign,_brief_text
from math_collab.proof_obligations import load_graph,validate_graph
root=Path.cwd();rel=Path('rounds/codex-managed/gc-upper-tail-separated-products');base=root/rel
for n in ['briefs','reports','candidates','reviews','controls/prelaunch_state']: (base/n).mkdir(parents=True,exist_ok=True)
def read(p):return json.loads(p.read_text(encoding='utf-8'))
def write(p,d):p.write_text(json.dumps(d,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
old=read(root/'state/active_campaign.yml');assert old['round_index']==231 and old['status']=='complete'
graph=load_graph(root/'state/proof_obligations.yml');assert not validate_graph(graph,root=root)
gh=sha(root/'state/proof_obligations.yml');assert gh==old['starting_graph_sha256']
allowed=read(root/'rounds/codex-managed/gc-actual-upper-tail-a/plan.json')['artifact_policy']['allowed_workflow_changes']
inventory={p.relative_to(root).as_posix():sha(p) for top in ['state','rounds','proofs/kernels','strategy','manifests'] for p in (root/top).rglob('*') if p.is_file() and base not in p.parents and p.suffix!='.pyc'}
write(base/'controls/starting_hashes.json',inventory)
for name in allowed:
 p=root/name
 if p.exists():(base/'controls/prelaunch_state'/p.name).write_bytes(p.read_bytes())
now=datetime.now(timezone.utc).isoformat()
common=['protocol.md','state/proof_obligations.yml','state/active_campaign.yml',(rel/'briefs/actual_interface.md').as_posix(),'rounds/codex-managed/gc-actual-upper-tail-a/synthesis.md','rounds/codex-managed/gc-actual-upper-tail-a/reports/signed_upper_tail_attack.md','rounds/codex-managed/gc-actual-upper-tail-a/reports/resonance_hostile_controls.md','rounds/codex-managed/gc-actual-upper-tail-a/reviews/independent_signed_tail_review.md','proofs/kernels/gc_complete_square_root_large_values_moment_bound.md']
controls=['actual_packet_definition','same_product_and_near_pairs','separated_signed_target','selected_set_not_slow_test','all_scales_tails_errors','non_psd_band_control','both_tail_complete_budget','blind_isolation','graph_and_history_preservation']
specs=[
 ('actual_near_product_payment','formalizer','selected_context','Prove or repair the candidate exact/near-product restricted-energy payment in actual_interface.md, including all-q exterior and negative tails, cross-rectangle packet grouping, exact powers, real endpoints, and errors on E. Determine the strongest legal product separation cutoff and the full complete-moment implication of the separated signed remainder. Produce genuine component bounds if available, but do not call the remaining target proved. Independently test the claimed collision payment and scopes. About12 minutes, one report.',common),
 ('separated_product_attack','discovery','selected_context','Attempt the actual separated-product signed correlation target after the proposed close-sector payment. Use reduced gcd/product-difference arithmetic, retain the actual full-wave E, and seek a quantitative bound beyond the accepted zero-power energy. Distinguish fixed-difference sign rigidity from cancellation between shifts. Explore one concrete summation/dispersion mechanism through its complete costs; show the precise first failed inequality if unsuccessful. Do not merely restate the representation or assume the near-sector lemma. About12 minutes, one report.',common),
 ('blind_packet_band','blind_rederiver','statement_only','Solve only isolated_packet_band.md. Derive sharp integer-center close-band bounds, cost all cross terms and give PSD/complementary-energy controls. No graph, actual context or siblings. Around10 minutes, one report.',['protocol.md',(rel/'briefs/isolated_packet_band.md').as_posix()])]
tasks=[]
for id,role,mode,target,context in specs:
 t={'id':id,'role':role,'access_mode':mode,'target':target,'context_files':context,'required_controls':controls if mode!='statement_only' else ['non_psd_band_control','blind_isolation'],'required_output':['Seven protocol sections; exact proof/gap, control, context hashes, state recommendation.','Write only assigned report; freeze SHA256 and stop.'],'status':'assigned','report_path':(rel/'reports'/(id+'.md')).as_posix()}
 if mode=='statement_only':t['excluded_context']=['All files except protocol.md, isolated_packet_band.md and own brief; no graph, actual interface or sibling/history reports.']
 tasks.append(t)
manifest={'schema_version':1,'round_index':232,'round_type':'bounded_separated_product_upper_tail_attempt','campaign_id':'gc-upper-tail-separated-products','title':'Pay close products and attack actual separated-product covariance','status':'active','max_concurrency':3,'coordinator':'Codex','generated_at':now,'user_date':'2026-10-12 Asia/Shanghai','starting_graph_sha256':gh,'attempt_on_current_premise':2,'resource_policy':{'analytical_algebraic_minimum_percent':95,'numerical_experimental_maximum_percent':5,'budget':'Three initial10-12 minute tasks, one nonauthor review/repair cycle; mandatory strategy reassessment at closure if no gain; no automatic successor.'},'target_obligations':['GC-target','GC-complete-square-root-large-values-moment-bound'],'frozen_target':{'question':'Can exact and nearby product collisions be paid below the required exceptional-set energy, and can the remaining actual signed separated-product correlations yield complete32/25?','reference_formula':'E={|F_(16/125)|>T^(16/125)}, Q_E<=T^(-a*+epsilon), a*=10beta-32/25. Prove close-pair payment for |p-pprime|<=sqrt(T); attempt the remaining one-sided signed correlation at -a*.','quantities':['Literal actual full band and full-wave exceptional set.','Candidate near bound T^(-3/250+epsilon) must be proved.','All product modes, rectangles, tails, selected-set errors and full moment owners retained.','A component gain is not a complete theorem; same-premise attempt2 does not reset via an equivalent transform.']},'completion_criteria':['Three frozen initial reports or explicit termination.','Statement-only independent derivation plus nonauthor review of actual payment and separated attack.','Bounded exact adversarial controls; all scientific claims scoped.','Complete ledger, first gap, mandatory same-premise strategy reassessment.','Green scoped gates and valid State Patch; graph/draft protected unless full promotion justified.','Ledger closure before any successor; no automatic Round233.'],'controls':controls,'tasks':tasks,'review_seams':[{'id':'actual_payment','requirement':'Exact packets, tails, cross terms and exceptional-set power'},{'id':'signed_attack','requirement':'Gcd/shift summation, actual E and complete cost'},{'id':'blind_band','requirement':'Integer convolution bound and non-PSD controls'},{'id':'complete_restoration','requirement':'Both tails and complete benchmark'}],'exit_labels':['separated_product_complete_gain_requires_promotion','separated_product_attempt_closed_without_complete_gain'],'conductor_interventions':['User continuation authorizes the next bounded round after closed231.','Near-pair subtraction is the concrete proposed bypass of the localized collision control; it does not assume pairwise decorrelation.']}
assert not validate_campaign(manifest,graph,root=root)
write(root/'state/active_campaign.yml',manifest)
write(base/'plan.json',{'campaign':manifest,'provenance':{'graph_path':'state/proof_obligations.yml','graph_sha256':gh,'generated_at':now},'artifact_policy':{'state_owner':'conductor_only','computation':'diagnostic_only','allowed_workflow_changes':allowed}})
for t in tasks:(base/'briefs'/(t['id']+'.md')).write_text(_brief_text(manifest,t,graph_hash=gh,generated_at=now)+'\nWrite ONLY `'+t['report_path']+'`. Freeze and stop.\n',encoding='utf-8')
ledger=read(root/'state/round_ledger.yml');prior=read(base/'controls/prelaunch_state/round_ledger.yml');assert ledger==prior and not any(r['round_index']==232 for r in ledger['rounds'])
ledger['active_round']=232;ledger['rounds'].append({'round_index':232,'campaign_id':manifest['campaign_id'],'type':manifest['round_type'],'status':'active','objective':manifest['frozen_target']['question'],'started_at':now,'starting_graph_sha256':gh,'attempt_on_current_premise':2,'tasks':[{'id':t['id'],'role':t['role'],'status':'assigned'} for t in tasks],'resource_policy':manifest['resource_policy']});write(root/'state/round_ledger.yml',ledger)
future=read(root/'state/next_round_plan.yml');future.update(status='active',campaign_id=manifest['campaign_id'],tasks=[t['id'] for t in tasks],candidate_objective=manifest['frozen_target']['question'],launch_record={'started_at':now,'campaign':manifest['campaign_id'],'attempt_on_current_premise':2,'authorization':'User: keep going after closed231.'});write(root/'state/next_round_plan.yml',future)
summary='# Round232 active: separated-product upper-tail attempt\n\n12 October2026. Pay exact/near-product contributions on the actual exceptional set, then attempt the remaining signed separated-product covariance. Three bounded orthogonal tasks, independent review and closure required. This is attempt2 on the upper-tail premise; reassess strategy at closure if no complete gain. Accepted graph/draft unchanged.\n\nCampaign: '+(rel/'plan.json').as_posix()+'.\n'
for name in ['state/current_round.md','state/next_campaign.md']:(root/name).write_text(summary,encoding='utf-8')
barrier='# Round232 active barrier packet\n\nThe actual selected set E is retained. Exact/near product collisions must be paid, not deleted. The close-band matrix is not automatically positive. No arbitrary-mask ceiling, pairwise decorrelation, slow-indicator replacement, or unsigned shifted-product estimate implies a gain. Full second-Poisson modes, transitions, small factors, all errors and complete owners remain. Attempt2 requires reassessment if no complete gain.\n\nInterface: '+(rel/'briefs/actual_interface.md').as_posix()+'.\n\n---\n\n'
p=root/'state/failure_ledger.md';p.write_bytes(barrier.encode('utf-8')+p.read_bytes())
assert read(root/'state/round_ledger.yml')['rounds'][:-1]==prior['rounds']
print(json.dumps({'status':'active','round':232,'attempt':2,'tasks':len(tasks),'protected_files':len(inventory),'graph_sha256':gh}))
